-- Migration: Year 2 - Renal/Urinary Pathology MCQ Bank (PART 3: 151-225)
-- Topics: Tubulointerstitial Diseases, Acute/Chronic Kidney Failure, Nephrolithiasis
-- Date: 2026-04-24

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Ensure Topic exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Renal/Urinary Pathology', 'renal-urinary-pathology', 3, 2, 50)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- ACUTE INTERSTITIAL NEPHRITIS (151-160)
    (v_topic_id, '151. Acute Interstitial Nephritis (AIN) is most commonly triggered by?', '["Bacterial infection", "Ischemia", "Medications (Drugs)", "Autoimmune disease"]', 2, 'AIN is usually a drug-induced hypersensitivity reaction involving the interstitium and tubules. The glomeruli are spared.'),
    (v_topic_id, '152. Which classic triad of symptoms suggests Acute Interstitial Nephritis?', '["Fever, Rash, and Eosinophilia", "Hypertension, Hematuria, and Proteinuria", "Flank pain, Hematuria, and Palpable mass", "Polyuria, Polydipsia, and Hypernatremia"]', 0, 'The classic hypersensitivity triad (occurring 1-2 weeks after starting a drug) includes fever, maculopapular rash, and eosinophilia (blood and urine), along with AKI.'),
    (v_topic_id, '153. Which drugs are notorious for causing Acute Interstitial Nephritis? (Remember the 5 P''s)', '["Pee (Diuretics), Pain-free (NSAIDs), Penicillins, PPIs, RifamPin", "Paracetamol, Propofol, Phenytoin, Prednisone, Penicillin", "Propylthiouracil, PTU, Prednisolone, PPIs", "Phenobarbital, Phenytoin, Primidone"]', 0, 'The 5 P''s: Pee (Diuretics), Pain-free (NSAIDs), Penicillins (and cephalosporins), PPIs (Proton Pump Inhibitors), and RifamPin.'),
    (v_topic_id, '154. What type of cells predominate in the interstitial infiltrate in AIN?', '["Neutrophils and RBCs", "Eosinophils and Mononuclear cells (T-cells/Macrophages)", "Plasma cells and B-cells", "Fibroblasts only"]', 1, 'The infiltrate is rich in eosinophils (Type I hypersensitivity component) and T-cells/macrophages (Type IV hypersensitivity component).'),
    (v_topic_id, '155. What is the typical appearance of the glomeruli in Acute Interstitial Nephritis?', '["Crescentic", "Sclerotic", "Normal", "Hypercellular"]', 2, 'The disease affects the tubulointerstitium. The glomeruli themselves are structurally normal and spared from inflammation.'),
    (v_topic_id, '156. How is AIN differentiated from Acute Tubular Necrosis (ATN) on urinalysis?', '["ATN has WBC casts, AIN has muddy brown casts", "AIN has WBC casts (often with eosinophils), ATN has muddy brown granular casts", "AIN has RBC casts, ATN has hyaline casts", "AIN has massive proteinuria, ATN has none"]', 1, 'AIN involves inflammation (WBCs, eosinophils). ATN involves tubular cell death (sloughing epithelial cells forming muddy brown casts).'),
    (v_topic_id, '157. Does drug-induced AIN resolve after stopping the offending agent?', '["No, it always progresses to CKD", "Yes, usually fully reversible if stopped early", "Only if treated with dialysis", "No, it causes permanent papillary necrosis"]', 1, 'Withdrawal of the offending drug usually leads to full recovery. Corticosteroids can be used if recovery is delayed.'),
    (v_topic_id, '158. Chronic Interstitial Nephritis (Analgesic Nephropathy) is caused by long-term use of?', '["Penicillin", "PPIs", "Aspirin/NSAIDs + Acetaminophen", "Diuretics"]', 2, 'Years of consuming mixed analgesics leads to cumulative toxicity, causing chronic tubulointerstitial fibrosis and papillary necrosis.'),
    (v_topic_id, '159. A classic complication of Chronic Analgesic Nephropathy is an increased risk for?', '["Renal Cell Carcinoma", "Transitional Cell Carcinoma of the renal pelvis", "Prostate cancer", "Bladder squamous cell carcinoma"]', 1, 'Chronic irritation and toxicity from analgesics (especially phenacetin/acetaminophen) increase the risk of urothelial (transitional cell) carcinoma in the renal pelvis.'),
    (v_topic_id, '160. NSAIDs can cause both AIN and which glomerular disease?', '["Minimal Change Disease", "Membranous Nephropathy", "PSGN", "FSGS"]', 1, 'NSAIDs are a unique trigger that can cause both AIN (tubular hypersensitivity) and Membranous Nephropathy (massive proteinuria).'),

    -- ACUTE TUBULAR NECROSIS (ATN) (161-175)
    (v_topic_id, '161. What is the most common cause of intrinsic Acute Kidney Injury (AKI) in hospitalized patients?', '["Acute Interstitial Nephritis", "Acute Tubular Necrosis (ATN)", "Rapidly Progressive GN", "Renal vein thrombosis"]', 1, 'ATN accounts for the vast majority of intrinsic AKI, usually due to ischemia (shock/hypotension) or nephrotoxins.'),
    (v_topic_id, '162. The hallmark finding on urinalysis in ATN is?', '["WBC casts", "RBC casts", "Muddy brown granular casts", "Hyaline casts"]', 2, 'Necrotic tubular epithelial cells slough off into the lumen, forming muddy brown granular casts.'),
    (v_topic_id, '163. Ischemic ATN most severely affects which parts of the nephron?', '["Glomerulus and Bowman capsule", "Proximal convoluted tubule and thick ascending limb of Henle", "Distal convoluted tubule and collecting duct", "Macula densa"]', 1, 'The PCT and thick ascending limb are highly metabolically active (lots of ATP pumps) and rely heavily on oxygen, making them the most susceptible to ischemic injury.'),
    (v_topic_id, '164. Nephrotoxic ATN (e.g., from Aminoglycosides or Contrast dye) primarily damages which segment?', '["Glomerulus", "Proximal convoluted tubule", "Thick ascending limb", "Collecting duct"]', 1, 'Toxins are filtered and concentrated in the PCT, making the PCT the primary target of direct toxic damage.'),
    (v_topic_id, '165. A patient undergoing a CT scan with IV contrast develops oliguria and rising creatinine 48 hours later. Diagnosis?', '["Contrast-induced nephropathy (a form of nephrotoxic ATN)", "Allergic AIN to iodine", "Renal artery thrombosis", "Postrenal obstruction"]', 0, 'Radiocontrast dye is directly toxic to the tubules and causes intense vasoconstriction, leading to ATN.'),
    (v_topic_id, '166. A crush injury victim presents with dark red urine. Urine dipstick is positive for "blood", but microscopy shows NO RBCs. Diagnosis?', '["Hematuria from bladder trauma", "Rhabdomyolysis causing Myoglobin-induced ATN", "Hemoglobinuria from mismatched transfusion", "Porphyria"]', 1, 'Crushed muscle releases massive amounts of myoglobin, which is directly toxic to the tubules. The dipstick cannot distinguish between hemoglobin and myoglobin, but microscopy will show no intact RBCs.'),
    (v_topic_id, '167. Which of the following is a classic cause of nephrotoxic ATN?', '["Ethylene glycol poisoning", "Penicillin allergy", "Group A Strep infection", "Dehydration"]', 0, 'Ethylene glycol (antifreeze) is metabolized to oxalate, which forms massive calcium oxalate crystals that physically destroy the tubules.'),
    (v_topic_id, '168. Tumor Lysis Syndrome causes ATN through the massive release of which substance?', '["Calcium", "Uric Acid", "Potassium", "Phosphate"]', 1, 'Rapid tumor cell death releases purines, which are converted to uric acid. Massive uric acid precipitates in the tubules, causing acute obstruction and ATN.'),
    (v_topic_id, '169. What is the typical clinical course of ATN?', '["Irreversible destruction", "Initiation -> Maintenance (oliguric) -> Recovery (polyuric) phases", "Immediate recovery within hours", "Chronic slow decline"]', 1, 'ATN has 3 phases. The maintenance phase features oliguria and rising BUN/Cr (high risk of hyperkalemia/acidosis). The recovery phase features polyuria as tubules regenerate but can''t concentrate urine yet (risk of hypokalemia/dehydration).'),
    (v_topic_id, '170. Can the tubular epithelial cells regenerate after ATN?', '["No, they are replaced by scar tissue", "Yes, as long as the tubular basement membrane remains intact", "Yes, but only in nephrotoxic ATN, not ischemic", "No, stem cells do not exist in the kidney"]', 1, 'Tubular cells have the capacity to regenerate. Ischemic ATN can sometimes rupture the basement membrane (tubulorrhexis), which impairs perfect regeneration, but functional recovery is usually possible.'),
    (v_topic_id, '171. In ATN, what happens to the BUN:Creatinine ratio?', '["It rises to > 20:1", "It stays < 15:1", "It becomes negative", "It fluctuates wildly"]', 1, 'Because the tubules are dead, they cannot reabsorb BUN. Both BUN and Cr rise proportionately in the blood, keeping the ratio < 15:1 (classic for intrinsic renal failure).'),
    (v_topic_id, '172. In ATN, what happens to the Fractional Excretion of Sodium (FENa)?', '["It is < 1%", "It is > 2%", "It is 0%", "It depends on fluid intake"]', 1, 'Dead tubules cannot reabsorb sodium. Sodium spills into the urine, making FENa > 2% and urine sodium > 40 mEq/L.'),
    (v_topic_id, '173. In Prerenal Azotemia (e.g., severe dehydration), what is the FENa?', '["< 1%", "> 2%", "> 5%", "Negative"]', 0, 'In prerenal states, the kidney is structurally intact and desperately tries to hold onto salt and water to restore volume, making FENa < 1% and urine sodium < 20 mEq/L.'),
    (v_topic_id, '174. In Prerenal Azotemia, what is the BUN:Creatinine ratio?', '["< 15:1", "> 20:1", "1:1", "10:1"]', 1, 'Aldosterone and ADH are high. ADH increases water reabsorption in the collecting duct, which passively drags urea (BUN) back into the blood, while Cr is not reabsorbed. The ratio rises > 20:1.'),
    (v_topic_id, '175. If a patient with Prerenal Azotemia is not resuscitated, what happens?', '["They develop postrenal obstruction", "They transition into Ischemic ATN", "They develop IgA nephropathy", "They recover spontaneously"]', 1, 'Prolonged ischemia eventually kills the tubular cells, transitioning the patient from a reversible prerenal state (<1% FENa) into an intrinsic renal failure state (>2% FENa).'),

    -- RENAL PAPILLARY NECROSIS (176-180)
    (v_topic_id, '176. Renal Papillary Necrosis is caused by ischemia to the renal papillae. What are the 4 classic triggers? (Remember mnemonic SAAD papa)', '["Sickle cell disease, Analgesics (NSAIDs), Acute pyelonephritis, Diabetes mellitus", "Syphilis, Aspirin, Adenovirus, DKA", "Scleroderma, ACE inhibitors, Amyloidosis, Diuretics", "Sarcoidosis, Alcohol, Autoimmune, Dialysis"]', 0, 'SAAD: Sickle cell, Analgesics, Acute pyelonephritis, Diabetes. These compromise the delicate blood supply to the papillae.'),
    (v_topic_id, '177. How does Renal Papillary Necrosis present clinically?', '["Massive proteinuria and edema", "Gross hematuria and flank pain (often colicky, mimicking a stone)", "Oliguria and anuria", "Painless microscopic hematuria"]', 1, 'The sloughing of the necrotic papilla into the ureter causes severe flank pain and gross hematuria as it passes.'),
    (v_topic_id, '178. What does imaging (IVP or CT urogram) show in advanced Renal Papillary Necrosis?', '["Enlarged cystic kidneys", "Ring shadow or ''golf ball on a tee'' appearance", "Shrunken, scarred kidneys", "Massive hydronephrosis"]', 1, 'The contrast fills the cavity left by the sloughed papilla, creating a "ring" or "golf ball on a tee" appearance at the calyx.'),
    (v_topic_id, '179. Can Renal Papillary Necrosis lead to renal failure?', '["Yes, rapidly", "Usually not, unless bilateral and severe", "Always", "It only causes isolated hematuria"]', 1, 'It typically does not cause acute renal failure unless it is bilateral and massive enough to cause obstruction. It is primarily a source of bleeding and pain.'),
    (v_topic_id, '180. Why do NSAIDs cause Renal Papillary Necrosis?', '["They directly burn the papillae", "They inhibit prostaglandins, which normally dilate the afferent arteriole to maintain medullary blood flow", "They cause massive crystal formation", "They induce an autoimmune attack on the papillae"]', 1, 'The medulla is already borderline hypoxic. Blocking vasodilatory prostaglandins starves the papillae of their remaining blood supply.'),

    -- NEPHROLITHIASIS (KIDNEY STONES) (181-195)
    (v_topic_id, '181. What is the most common type of kidney stone?', '["Calcium Phosphate", "Uric Acid", "Calcium Oxalate", "Struvite"]', 2, 'Calcium oxalate stones account for ~75-80% of all kidney stones.'),
    (v_topic_id, '182. A patient with Calcium Oxalate stones is advised to change their diet. What should they do regarding Calcium intake?', '["Severely restrict dietary calcium", "Maintain normal dietary calcium, but restrict sodium and oxalate", "Increase calcium intake massively", "Calcium intake has no effect"]', 1, 'Restricting dietary calcium paradoxically INCREASES the risk of stones, because free oxalate in the gut is no longer bound by calcium, leading to increased oxalate absorption and excretion in the urine. Restrict sodium (which decreases urine calcium) and oxalate (spinach, rhubarb).'),
    (v_topic_id, '183. Which vitamin overdose can lead to Calcium Oxalate stones?', '["Vitamin A", "Vitamin C (Ascorbic acid)", "Vitamin E", "Vitamin B12"]', 1, 'Vitamin C is metabolized to oxalate in the body. Massive doses can increase urine oxalate.'),
    (v_topic_id, '184. What shape do Calcium Oxalate crystals have on urine microscopy?', '["Coffin lids", "Rhomboid or rosettes", "Hexagonal", "Envelope or dumbbell shaped"]', 3, 'Calcium oxalate crystals are classically envelope (octahedral) or dumbbell shaped.'),
    (v_topic_id, '185. Calcium Phosphate stones form in what type of urine?', '["Acidic (pH < 5.5)", "Alkaline (pH > 7.0)", "Neutral exactly", "It doesn''t depend on pH"]', 1, 'Unlike oxalate, calcium phosphate precipitates in alkaline urine (e.g., in Renal Tubular Acidosis Type 1).'),
    (v_topic_id, '186. What shape do Calcium Phosphate crystals have?', '["Envelope", "Wedge-shaped prisms or rosettes", "Hexagonal", "Coffin lids"]', 1, 'They often appear as amorphous debris or wedge-shaped prisms/rosettes.'),
    (v_topic_id, '187. Ammonium Magnesium Phosphate (Struvite) stones are caused by?', '["Hyperparathyroidism", "Uric acid overproduction", "Infection with urease-positive bacteria (Proteus, Klebsiella)", "Genetic defect in amino acid transport"]', 2, 'Urease splits urea into ammonia, raising the urine pH (alkaline) and causing struvite precipitation.'),
    (v_topic_id, '188. Struvite stones famously grow to massive sizes, forming?', '["Staghorn calculi", "Microscopic gravel", "Bladder pearls", "Urethral plugs"]', 0, 'They form massive casts of the renal pelvis and calyces, known as staghorn calculi. They require surgical removal to eradicate the embedded bacteria.'),
    (v_topic_id, '189. What shape do Struvite crystals have?', '["Envelope", "Coffin lid", "Hexagonal", "Rhomboid"]', 1, 'Struvite crystals appear as "coffin lids".'),
    (v_topic_id, '190. Uric acid stones are unique among the major stone types because they are?', '["Radiopaque (visible on X-ray)", "Radiolucent (invisible on plain X-ray)", "Alkaline-forming", "Associated with Proteus"]', 1, 'Uric acid stones are radiolucent. They require CT scan or ultrasound for visualization.'),
    (v_topic_id, '191. Uric acid stones form in what type of urine?', '["Alkaline", "Highly acidic", "Neutral", "Only in the presence of bacteria"]', 1, 'Low urine pH drives uric acid precipitation. A major risk factor is chronic diarrhea (loss of bicarb leads to acidic urine) or gout/tumor lysis.'),
    (v_topic_id, '192. What shape do Uric acid crystals have?', '["Envelope", "Coffin lid", "Hexagonal", "Rhomboid or rosettes"]', 3, 'Uric acid crystals are pleomorphic, often rhomboid, needle-like, or forming rosettes.'),
    (v_topic_id, '193. Cystine stones are caused by?', '["A defect in purine metabolism", "An autosomal recessive defect in the PCT transporter for COLA amino acids", "Hypercalcemia", "Bacterial infection"]', 1, 'Cystinuria is a genetic defect in the reabsorption of Cystine, Ornithine, Lysine, and Arginine (COLA). Cystine is poorly soluble and precipitates.'),
    (v_topic_id, '194. What shape do Cystine crystals have?', '["Envelope", "Coffin lid", "Hexagonal", "Rhomboid"]', 2, 'Cystine crystals have a classic Hexagonal shape. (Six sides = Cystine).'),
    (v_topic_id, '195. How is Cystine stone formation treated?', '["Acidify the urine", "Alkalinize the urine (e.g., Potassium Citrate) and massive hydration", "Allopurinol", "Antibiotics"]', 1, 'Cystine is more soluble in alkaline urine. Alkalinizing the urine prevents precipitation.'),

    -- CHRONIC KIDNEY DISEASE (CKD) (196-210)
    (v_topic_id, '196. The most common cause of CKD in the developed world is?', '["Hypertension", "Glomerulonephritis", "Diabetes Mellitus", "Polycystic Kidney Disease"]', 2, 'Diabetes is #1, followed closely by Hypertension.'),
    (v_topic_id, '197. How does CKD affect serum calcium and phosphate levels?', '["High Ca, Low PO4", "Low Ca, High PO4", "High Ca, High PO4", "Normal Ca, Normal PO4"]', 1, 'Failing kidneys cannot excrete phosphate (High PO4). High PO4 binds free calcium. Also, the kidney cannot activate Vitamin D, further lowering Calcium absorption.'),
    (v_topic_id, '198. The hypocalcemia in CKD triggers which endocrine response?', '["Primary Hyperparathyroidism", "Secondary Hyperparathyroidism", "Tertiary Hyperparathyroidism", "Hyperthyroidism"]', 1, 'Low calcium stimulates the parathyroid glands to secrete massive amounts of PTH, causing bone resorption.'),
    (v_topic_id, '199. What is the characteristic bone disease seen in CKD due to high PTH?', '["Osteopetrosis", "Paget Disease", "Osteitis Fibrosa Cystica (Renal Osteodystrophy)", "Osteosarcoma"]', 2, 'High PTH causes subperiosteal bone resorption and brown tumors (cystic spaces filled with hemorrhage and giant cells).'),
    (v_topic_id, '200. Why do patients with CKD develop a bleeding diathesis?', '["Decreased platelet count", "Decreased clotting factor production", "Uremic toxins impair platelet aggregation and function", "Increased destruction of platelets in the spleen"]', 2, 'Uremia causes platelet dysfunction (qualitative defect). The platelet count is normal, but bleeding time is prolonged.'),
    (v_topic_id, '201. Why do patients with CKD develop anemia?', '["Iron deficiency", "Folate deficiency", "Decreased production of Erythropoietin (EPO) by renal interstitial fibroblasts", "Hemolysis from uremic toxins"]', 2, 'The failing kidney cannot produce EPO, leading to a normocytic, normochromic anemia.'),
    (v_topic_id, '202. What cardiovascular complication is the leading cause of death in ESRD?', '["Uremic pericarditis", "Myocardial infarction / Accelerated atherosclerosis", "Aortic dissection", "Endocarditis"]', 1, 'Cardiovascular disease (MI, heart failure) accounts for ~50% of deaths in dialysis patients, driven by hypertension, dyslipidemia, and vascular calcification.'),
    (v_topic_id, '203. Uremia can cause inflammation of which serosal surface, presenting with chest pain relieved by leaning forward?', '["Pleura", "Peritoneum", "Pericardium (Uremic Pericarditis)", "Meninges"]', 2, 'Uremic pericarditis presents with a friction rub and pleuritic chest pain. It is an absolute indication for emergency dialysis.'),
    (v_topic_id, '204. What happens to the acid-base balance in severe CKD?', '["Metabolic Alkalosis", "High Anion Gap Metabolic Acidosis", "Respiratory Acidosis", "Normal Anion Gap Metabolic Acidosis"]', 1, 'The failing kidney cannot excrete daily metabolic acids (sulfates, phosphates) or reabsorb sufficient bicarbonate, leading to a high anion gap metabolic acidosis (uremia).'),
    (v_topic_id, '205. Broad, waxy casts on urinalysis are indicative of?', '["Acute Tubular Necrosis", "Acute Glomerulonephritis", "Advanced Chronic Kidney Disease", "Normal concentrated urine"]', 2, 'As nephrons die and scar in CKD, the remaining functional tubules undergo compensatory hypertrophy and dilation. Casts forming in these dilated tubules are "broad". "Waxy" implies chronic stasis.'),
    (v_topic_id, '206. A patient with ESRD on hemodialysis for 15 years develops bilateral carpal tunnel syndrome. What is the cause?', '["Fluid overload", "Deposition of Beta-2 Microglobulin amyloid", "Nerve ischemia", "Uremic neuropathy"]', 1, 'Dialysis-associated amyloidosis (Beta-2 microglobulin) preferentially deposits in the carpal tunnel and joints.'),
    (v_topic_id, '207. Which of the following is a classic skin finding in severe, untreated uremia?', '["Jaundice", "Uremic frost", "Malar rash", "Palmar erythema"]', 1, 'Uremic frost occurs when sweat containing high concentrations of urea evaporates, leaving crystallized urea on the skin (rare now due to dialysis).'),
    (v_topic_id, '208. What is the mechanism of Renal Artery Stenosis leading to CKD?', '["Hypertensive damage", "Ischemic damage to the tubulointerstitium causing atrophy", "Autoimmune destruction", "Massive infarction"]', 1, 'Chronic reduction in blood flow causes ischemic atrophy of the kidney (it becomes shrunken).'),
    (v_topic_id, '209. In unilateral renal artery stenosis, how does the unaffected (contralateral) kidney appear?', '["Shrunken and ischemic", "Normal or enlarged (compensatory hypertrophy) but often suffers hypertensive damage", "Cystic", "Necrotic"]', 1, 'The stenotic kidney is shrunken/protected from high pressure. It secretes massive renin, causing systemic hypertension. The contralateral normal kidney bears the brunt of this high blood pressure and develops hypertensive nephrosclerosis.'),
    (v_topic_id, '210. The characteristic histologic finding of hypertensive nephrosclerosis is?', '["Hyaline arteriolosclerosis", "Hyperplastic arteriolosclerosis", "Fibrinoid necrosis", "Crescents"]', 0, 'Chronic benign hypertension causes proteins to leak into the vessel wall, producing thick, pink hyaline arteriolosclerosis (especially in the afferent arteriole).'),

    -- POSTRENAL FAILURE (211-225)
    (v_topic_id, '211. What is the most common cause of Postrenal AKI in elderly men?', '["Bilateral kidney stones", "Urethral stricture", "Benign Prostatic Hyperplasia (BPH)", "Prostate cancer"]', 2, 'BPH is the overwhelming leading cause of urinary retention and bilateral obstruction in older men.'),
    (v_topic_id, '212. To cause acute renal failure (elevated Cr), a kidney stone must obstruct?', '["One ureter", "Both ureters (or one ureter in a patient with a single functioning kidney)", "The renal pelvis", "The major calyx"]', 1, 'Unilateral obstruction does NOT cause a significant rise in systemic Creatinine because the contralateral normal kidney perfectly compensates. Postrenal AKI requires bilateral obstruction or obstruction at the urethra/bladder neck.'),
    (v_topic_id, '213. What happens to the BUN:Creatinine ratio in early Postrenal AKI?', '["< 15:1", "> 20:1", "1:1", "Negative"]', 1, 'In early obstruction, the high back-pressure forces urea (BUN) back into the blood, but not creatinine. The ratio resembles prerenal (> 20:1).'),
    (v_topic_id, '214. What happens to the BUN:Creatinine ratio in LATE Postrenal AKI (after days of obstruction)?', '["It remains > 20:1", "It drops to < 15:1", "It normalizes", "It rises to 50:1"]', 1, 'Prolonged back-pressure damages the tubular epithelial cells, converting the postrenal state into intrinsic Acute Tubular Necrosis. The dead tubules can no longer reabsorb BUN, so the ratio falls < 15:1.'),
    (v_topic_id, '215. What happens to the FENa in LATE Postrenal AKI?', '["< 1%", "> 2%", "0%", "Negative"]', 1, 'Because it has transitioned to ATN, the damaged tubules cannot reabsorb sodium, so FENa rises > 2%.'),
    (v_topic_id, '216. Massive, prolonged urinary tract obstruction leads to which morphological change in the kidney?', '["Hypertrophy", "Hydronephrosis and cortical atrophy", "Cyst formation", "Hemorrhage"]', 1, 'The immense back-pressure dilates the renal pelvis and calyces (hydronephrosis) and compresses the renal cortex, leading to ischemic atrophy (a paper-thin cortex).'),
    (v_topic_id, '217. A patient presents with acute flank pain radiating to the groin. Diagnosis?', '["Pyelonephritis", "Renal Cell Carcinoma", "Ureteral stone (Renal colic)", "Appendicitis"]', 2, 'Colicky pain radiating from flank to groin is the classic presentation of a ureteral calculus passing down the ureter.'),
    (v_topic_id, '218. Where is the most common site for a kidney stone to become impacted?', '["Ureteropelvic junction", "Pelvic brim", "Ureterovesical junction (where ureter enters bladder)", "Renal calyx"]', 2, 'The UVJ is the narrowest point of the entire urinary tract.'),
    (v_topic_id, '219. A pregnant woman develops right-sided hydronephrosis without a stone. Why?', '["The fetus produces excess urine", "The gravid uterus compresses the right ureter", "Increased progesterone relaxes the bladder", "Preeclampsia causes obstruction"]', 1, 'The enlarged uterus physically compresses the ureters at the pelvic brim. It is more common on the right due to the protective position of the sigmoid colon on the left.'),
    (v_topic_id, '220. Retroperitoneal fibrosis can cause bilateral ureteral obstruction. It is classically associated with which drugs?', '["NSAIDs", "Ergot alkaloids (e.g., methysergide) or IgG4 disease", "Penicillin", "Chemotherapy"]', 1, 'Methysergide and idiopathic IgG4-related disease are classic causes of a dense fibrotic mass encasing the retroperitoneal structures.'),
    (v_topic_id, '221. A patient with a neurogenic bladder (e.g., from spinal cord injury) is at risk for?', '["Vesicoureteral reflux, chronic pyelonephritis, and hydronephrosis", "Renal Cell Carcinoma", "Minimal Change Disease", "Renal artery stenosis"]', 0, 'Loss of bladder coordination leads to high bladder pressures, forcing infected urine backwards up the ureters, destroying the kidneys.'),
    (v_topic_id, '222. What is the classic finding on renal ultrasound in a patient with acute postrenal failure?', '["Small echogenic kidneys", "Normal kidneys", "Bilateral hydronephrosis", "Massive cystic kidneys"]', 2, 'Ultrasound is the test of choice and will show a dilated collecting system (hydronephrosis) bilaterally if the obstruction is at the bladder/urethra.'),
    (v_topic_id, '223. Sudden relief of a severe bilateral urinary obstruction results in?', '["Immediate return to normal function", "Post-obstructive massive diuresis", "Anuria", "Malignant hypertension"]', 1, 'The kidneys, damaged by back-pressure and loaded with retained urea/osmoles, will produce massive amounts of urine (often >1 L/hour) once unblocked. The patient must be aggressively hydrated to prevent shock.'),
    (v_topic_id, '224. Which type of incontinence is caused by bladder outlet obstruction (like BPH)?', '["Stress incontinence", "Urge incontinence", "Overflow incontinence", "Functional incontinence"]', 2, 'The bladder cannot empty against the obstruction. It fills to maximum capacity until the pressure overcomes the sphincter, causing continuous dribbling (overflow).'),
    (v_topic_id, '225. A newborn male is noted to have a poor urinary stream and bilateral hydronephrosis. Diagnosis?', '["Posterior urethral valves", "Hypospadias", "Epispadias", "Cryptorchidism"]', 0, 'Posterior urethral valves are a congenital membrane blocking the urethra in males, causing massive back-pressure, hydronephrosis, and potentially Potter sequence in utero.');

    RAISE NOTICE 'SUCCESS: Renal Pathology MCQs Part 3 (151-225) registered.';
END $$;

COMMIT;
